System.assertEquals(d,d); System.assertEquals(false,d.equals(otherDocument)); System.assertNotEquals(null,d.hashCode()); System.assertNotEquals(d.hashCode(),otherDocument.hashCode()); System.assert(d.toString().contains('root')); System.assertNotEquals(d.toString(),otherDocument.toString());
dom.XmlNode constructedNode = new dom.XmlNode(); System.assertNotEquals(null,constructedNode); dom.XmlNode n = d.getRootElement(); dom.XmlNode otherNode = otherDocument.getRootElement();
