dom.XmlNodeType c = dom.XmlNodeType.COMMENT; dom.XmlNodeType t = dom.XmlNodeType.TEXT;
System.assertEquals(c,c); System.assertEquals(false,c.equals(t)); System.assertNotEquals(null,c.hashCode()); System.assertNotEquals(c.hashCode(),t.hashCode());
XmlStreamReader r = new XmlStreamReader('<?xml version="1.0"?><p:root xmlns:p="urn:p" p:id="7"/>');
r.setNamespaceAware(true); r.next(); r.next();
System.assertEquals('Line: 1 Column: 56', r.getLocation());
